import { css } from '../styled-system/css';
import type { ParentComponent } from 'solid-js';

// Card layout class defined at module scope — Panda CSS css() returns a static class string
const cardClass = css({
  _dark: {
    bg: 'neutral.800',
    borderColor: 'neutral.600',
    shadow: 'none',
  },
  border: '1px solid',
  borderColor: 'gray.200',
  borderRadius: '2xl',
  margin: '6',
  marginX: 'auto',
  padding: '4',
  shadow: 'md',
  width: '2/3',
});

export const Card: ParentComponent<{ class?: string }> = (props) => (
  <div class={`${cardClass}${props.class ? ` ${props.class}` : ''}`}>
    {props.children}
  </div>
);

// ── src/components/Link.tsx ──
import { A } from '@solidjs/router';
import { css } from '../styled-system/css';
import type { ComponentProps } from 'solid-js';

// Link styles defined at module scope for performance
const linkClass = css({
  _dark: { color: 'pink.400' },
  _hover: { textDecoration: 'none' },
  color: 'pink.700',
  textDecoration: 'underline',
});

type LinkProps = ComponentProps<typeof A>;

// Thin wrapper around @solidjs/router's <A> component with consistent link styling
export const Link = (props: LinkProps) => (
  <A
    class={linkClass}
    {...props}
  >
    {props.children}
  </A>
);

