import { createSignal } from 'solid-js';
import { css } from '../styled-system/css';
import { flex } from '../styled-system/patterns';

// Styles defined at module scope
const counterClass = css({
  fontSize: '3xl',
  fontWeight: 'bold',
  color: 'pink.700',
  _dark: { color: 'pink.400' }
});

const buttonClass = css({
  bg: 'pink.600',
  color: 'white',
  paddingX: '4',
  paddingY: '2',
  borderRadius: 'md',
  _hover: { bg: 'pink.700' }
});

export const Counter = () => {
  const [count, setCount] = createSignal(0);

  return (
    <div class={flex({ direction: 'column', gap: '4', align: 'center' })}>
      <div class={counterClass}>Count: {count()}</div>
      <button 
        class={buttonClass}
        onClick={() => setCount((prev) => prev + 1)}
      >
        Increment
      </button>
    </div>
  );
};

